#include <iostream>
#include <vector>
using namespace std;

class Forme {
    public:
        virtual double aire() const = 0;
        virtual ~Forme() {}
};

class Rectangle : public Forme {
    private:
        double l, h;
    public:
        Rectangle(double l, double h) : l(l), h(h) {}
        double aire() const override { return l * h; }
};

class Carre : public Forme {
    private:
        double c;
    public:
        Carre(double c) : c(c) {}
        double aire() const override { return c * c; }
};

int main() {
    vector<Forme*> formes;
    formes.push_back(new Rectangle(3, 4));
    formes.push_back(new Carre(5));
    double total = 0;
    for (Forme* f : formes) {
        total += f->aire();
    }
    cout << "aire totale = " << total << endl;
    for (Forme* f : formes) delete f;
    return 0;
}

