#include <iostream>
using namespace std;

template <typename T>
class Paire {
    private:
        T premier;
        T second;
    public:
        Paire(T p, T s) : premier(p), second(s) {}
        T plusGrand() const {
            return (premier > second) ? premier : second;
        }
        void echanger() {
            T tmp = premier;
            premier = second;
            second = tmp;
        }
        void afficher() const {
            cout << "(" << premier << ", " << second << ")" << endl;
        }
};

int main() {
    Paire<int> pi(7, 3);
    pi.afficher();
    cout << "max = " << pi.plusGrand() << endl;
    pi.echanger();
    pi.afficher();

    Paire<char> pc('b', 'm');
    cout << "max = " << pc.plusGrand() << endl;
    return 0;
}

