#include <iostream>
#include <exception>
#include <string>
using namespace std;

class SoldeInsuffisant : public exception {
    private:
        string message;
    public:
        SoldeInsuffisant(int manque)
            : message("retrait refuse, il manque " + to_string(manque)) {}
        const char* what() const noexcept override {
            return message.c_str();
        }
};

class Compte {
    private:
        int solde;
    public:
        Compte(int s) : solde(s) {}
        void retirer(int montant) {
            if (montant > solde)
                throw SoldeInsuffisant(montant - solde);
            solde -= montant;
            cout << "retrait de " << montant << ", solde " << solde << endl;
        }
};

int main() {
    Compte c(100);
    int retraits[] = { 30, 90, 40 };
    for (int i = 0; i < 3; i++) {
        try {
            c.retirer(retraits[i]);
        }
        catch (const exception& e) {
            cout << e.what() << endl;
        }
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <string>
using namespace std;

struct Produit {
    string nom;
    int prix;
};

class ParPrixCroissant {
    public:
        bool operator()(const Produit& a, const Produit& b) const {
            return a.prix < b.prix;
        }
};

int main() {
    vector<Produit> panier = {
        { "stylo", 3 },
        { "cahier", 5 },
        { "gomme", 1 },
        { "regle", 2 }
    };
    sort(panier.begin(), panier.end(), ParPrixCroissant());
    for (const Produit& p : panier)
        cout << p.nom << " " << p.prix << endl;
    cout << "le moins cher: " << panier.front().nom << endl;
    return 0;
}
